                            + column + 1;
                        facequads[face_offset].vertex_2 =
                            (row + 1)
                                * ((unsigned short)path->width_cells + 1)
                            + column + 1;
                        facequads[face_offset].vertex_3 =
                            column
                            + (row + 1)
                                * ((unsigned short)path->width_cells + 1);
