                ->transform.basis_up = fixed_up;
            ((PathTemplateSample*)((char*)primary_samples + sample_offset))
                ->transform.basis_forward =
                ((PathTemplateSample*)((char*)primary_samples + sample_offset))
                    ->transform.position -
                ((PathTemplateSample*)((char*)primary_samples + sample_offset))[-1]
                    .transform.position;
